import type {ResearchPost} from './fleet-data';

export const november17ResearchBatch:readonly ResearchPost[]=[{"slug":"callcenteroutsourced-how-should-a-contact-center-plan-staffing-for-a-hurricane-season-surge","title":"How should a contact center plan staffing for a hurricane season surge?","excerpt":"A surge plan that defines the trigger, protects essential queues, and tests a short-notice staffing change before the storm arrives.","published":"2026-11-17","sourceDate":"2026-11-17","updated":"2026-11-17","image":"/daily17/callcenteroutsourced/callcenteroutsourced-how-should-a-contact-center-plan-staffing-for-a-hurricane-season-surge.webp","sections":[{"heading":"Question and scope","body":"This brief asks how an outsourced contact center should plan staffing for a hurricane-season surge. The population is one client queue and its supporting sites during a defined season, and the unit is a staffing interval. The question is whether the plan can add capacity, protect essential calls, and recover without exhausting the team. The analysis covers triggers, roles, and exercises, not the meteorological forecast. Record the sites, the client's essential functions, and the planning period before testing the plan."},{"heading":"What the evidence supports","body":"Federal continuity guidance calls for identifying essential functions, setting orders of succession, and exercising the plan before an emergency. Workforce and contact-center standards call for forecasting, scheduling, and performance measurement, but they do not supply one surge formula. The operating inference is to tie a staffing trigger to a measurable event and to a short list of protected queues. A plan that only names a headcount without a trigger cannot be activated consistently."},{"heading":"Define the surge trigger","body":"Write the events that start the surge plan, such as a declared emergency, a site closure, or a call-volume threshold that persists for two intervals. Name who can pull the trigger and who must confirm it. Include a lower threshold for a warning stage so the team can prepare before the volume arrives. A trigger that depends on a manager's intuition will be applied differently on every shift."},{"heading":"Separate essential from deferrable work","body":"List the calls the client must answer during a surge, such as safety, outage, and payment-failure lines. Put the deferrable work, including surveys and outbound campaigns, in a queue that can pause. Give each essential queue a minimum coverage rule and an owner. The list should be short enough to use when several managers are making decisions at once. The client should sign the list before the season so the order is not negotiated during a storm."},{"heading":"Map the capacity you can actually add","body":"Count the trained agents who can move to the essential queues, including part-time staff, supervisors, and a second site. Check the systems access and the client-specific training each person needs. Do not count people who would need a week of onboarding as same-day capacity. Record the lead time for each source so the plan shows when the help arrives. Record the shift each person can actually work, because a name on a list is not an available body."},{"heading":"Set a short-notice schedule rule","body":"A surge schedule needs a rule for overtime, rest periods, and shift changes that the client and the legal team have reviewed. A long extra shift can add coverage today and create an absence tomorrow. Write the maximum consecutive hours and the minimum rest before the next shift. Record who approves an exception and how the approval is stored. The schedule should show the rest time on the face of the plan, not in a separate policy."},{"heading":"Protect the team from a second disaster","body":"A storm can affect the agents as well as the customers. Check the transportation, power, and internet risks at each site and the work-from-home fallback. Keep a contact list that does not depend on the office network. Plan for a team member who cannot work and for a supervisor who must cover two queues. The capacity plan should include the people who deliver it."},{"heading":"Stage the client communication","body":"Agree with the client on what the queue will announce before the surge, during it, and after it. The message should state the current wait, the essential queues, and the next update time. Do not promise a recovery date that the forecast cannot support. Record the approved wording and the person who can change it. Name the client contact who can approve a change to the message during the event."},{"heading":"Test one trigger with a tabletop drill","body":"Run a short tabletop exercise with the client, the site leads, and one supervisor. Present a closure, a volume spike, and a system outage in sequence. Ask each role what they would do and where the plan is unclear. Record the decisions and the gaps. A tabletop finds coordination problems before they cost a live queue. End the drill with three fixes and a date, not a general agreement that the plan is good."},{"heading":"Test a live staffing move","body":"Choose a low-risk interval and move a small group to an essential queue as the plan describes. Measure the time to access, the first call handled, and the effect on the original queue. Do not use a simulated call for the whole test because the real systems are part of the risk. Record what broke and who fixed it. Keep the original queue's service level in the comparison so the test does not hide a new gap."},{"heading":"Reconcile the forecast with the plan","body":"Compare the volume the plan anticipated with the volume that arrived during a real event or a near miss. Separate the forecast error from the staffing response. A plan that added the right number of people too late still failed the customer. Update the trigger and the lead times with the observed data. Record the forecast error and the staffing delay as separate lines in the after-action note."},{"heading":"Review the vendor and site dependencies","body":"A surge plan can depend on a phone carrier, a cloud platform, a transport provider, and a backup site. List each dependency, its owner, and its own continuity plan. Ask for the recovery time the vendor promises and test one contact path. A plan that assumes a vendor will be available without evidence is a hope, not a control. Ask each vendor for a named escalation contact and the last date its recovery time was tested."},{"heading":"Set a recovery and stand-down rule","body":"The surge ends when the essential queues return to their normal service level for a defined period. Write the stand-down rule before the event so no one keeps the emergency schedule out of habit. Plan a short rest period and a review after the stand-down. Record who authorizes the return to normal hours. The stand-down should include a short rest period before the normal schedule resumes."},{"heading":"Check the client's own continuity plan","body":"The client may move its own staff, change its hours, or redirect calls during an emergency. Ask for the relevant section of the client's continuity plan and compare it with the vendor plan. Identify the decisions the client must make and the ones the queue can make. A mismatch in authority can leave both teams waiting. Write the decision rights in one table so each team knows which calls it can redirect."},{"heading":"Report the cost of the surge","body":"Track the overtime, the added hours, the paused work, and the service result for the surge period. Report the cost beside the protected calls, not in isolation. A surge that spends heavily on a deferrable queue is a poor trade. The client should see what the plan bought and what it displaced. Compare the surge cost with the value of the protected calls and the deferrable work that waited."},{"heading":"Test a communication failure","body":"Assume the primary chat and email channels are unavailable during the surge. Ask the team to use the backup contact list and the approved phone bridge. Time how long it takes to reach every lead. A plan that depends on one channel is fragile in the same event that causes the surge. Print the backup list and keep a copy outside the office network."},{"heading":"Review the legal and recordkeeping limits","body":"A surge may change schedules, breaks, and overtime in ways that labor rules and the client contract restrict. Ask counsel and the client to confirm the limits before the season. Record the approvals and the exceptions in the same file as the schedule. Do not let urgency create an undocumented pay or rest violation. Record the approval for each exception in the same file as the affected shift."},{"heading":"Write the after-action note","body":"After an event or a drill, write one page with the trigger, the actions, the result, and the gaps. Name an owner and a due date for each fix. Keep the note with the plan so the next season starts from evidence. Do not rewrite the plan to hide a missed step. Share the note with the client and the floor within a week, while the details are still fresh."},{"heading":"Limits of the evidence","body":"This brief cannot predict a storm, a site closure, or the exact volume a client will receive. A staffing plan can show a tested process, but it cannot guarantee that people, power, and networks will be available. The analysis covers one queue and its dependencies, not a regional emergency system. Use the result to expose a weak link, not to claim readiness."},{"heading":"Manager review questions","body":"Managers should ask what starts the plan, which queues are protected, and who can add capacity today. They should also ask when the plan was last tested and which vendor dependency has no verified recovery time. The remaining question is what the team will stop doing during the surge. Record the answers with the season and the test date. They should also ask which fix from the last drill is still open and who owns it."},{"heading":"Conclusion","body":"A hurricane-season staffing plan is credible when it names a trigger, protects essential queues, maps real capacity, and tests a short-notice move. It also needs a rest rule, a client communication path, and a stand-down decision. A headcount without those pieces is not a plan. The queue is ready when the team can activate the plan, measure the result, and return to normal without a second crisis."}],"sources":[{"name":"Business Continuity Plan","organization":"Ready.gov, Federal Emergency Management Agency","date":"2026","url":"https://www.ready.gov/business-continuity-plan","note":"Federal guidance on continuity planning, essential functions, and recovery exercises."},{"name":"Prepare for Emergencies","organization":"U.S. Small Business Administration","date":"2026","url":"https://www.sba.gov/business-guide/manage-your-business/prepare-for-emergencies","note":"Business continuity and disaster preparation guidance for small employers."},{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2026","url":"https://www.dol.gov/agencies/whd/flsa","note":"Federal minimum wage, overtime, hours-worked, and recordkeeping obligations."},{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."}],"keyStats":["2.67 million U.S. customer service representative jobs in 2025 (BLS)","$21.53 median hourly wage in May 2025 (BLS)","289,500 projected annual openings, 2025 to 2035 (BLS)"],"takeaways":["Tie the surge trigger to a declared event or a volume threshold held for two intervals.","Protect a short list of essential queues and pause surveys and outbound work by rule.","Count only trained, system-ready people as same-day capacity and record each source's lead time.","Test one live staffing move and write a one-page after-action note with owners."],"faqs":[{"question":"Should the surge plan include work-from-home agents?","answer":"Yes, if they have the systems access, the client training, and a power and internet fallback. Test the access before the season, not during the storm."},{"question":"When should the plan end?","answer":"When protected queues meet their normal service level for a defined period. Write the stand-down rule in advance so the emergency schedule does not continue by habit."}],"related":["callcenteroutsourced-how-should-a-split-shift-timekeeping-record-reconcile-with-the-schedule","callcenteroutsourced-what-does-a-call-recording-retention-schedule-prove-under-review"],"internalLinks":["/research","/services","/contact-us"],"serviceHandoff":{"href":"/contact-us","label":"Review the queue design","body":"Bring the current queue rules, the shift handoff, and one week of cases so the review can test a real promise."}},{"slug":"callcenteroutsourced-what-does-an-abandoned-call-log-prove-about-a-staffing-shortfall","title":"What does an abandoned-call log prove about a staffing shortfall?","excerpt":"A method for reading an abandoned-call log: separate queue design, customer behavior, and real capacity gaps before adding staff.","published":"2026-11-17","sourceDate":"2026-11-17","updated":"2026-11-17","image":"/daily17/callcenteroutsourced/callcenteroutsourced-what-does-an-abandoned-call-log-prove-about-a-staffing-shortfall.webp","sections":[{"heading":"Question and scope","body":"This brief asks what an abandoned-call log can prove about a staffing shortfall in an outsourced contact center. The population is one queue during a defined period, and the unit is a call that left before an agent answered. The question is whether the log shows a capacity gap or another cause, such as a menu delay or a sudden outage. The analysis covers measurement and review, not the commercial case for a headcount change. Record the queue, the period, and the platform before sampling."},{"heading":"What the evidence supports","body":"Contact-center standards call for measuring abandoned calls and service level together, and federal data-quality guidance calls for documenting sources and limitations. Neither source says that a specific abandon rate proves a staffing shortfall. The operating inference is to compare abandoned calls with offered volume, wait time, agent availability, and the point of abandonment. A single rate without those comparisons is a symptom, not a diagnosis."},{"heading":"Define the abandoned call","body":"An abandoned call is a customer who leaves the queue before an agent answers. Decide how to treat a caller who hangs up during the greeting, during a menu, or after a transfer. Each point of abandonment has a different cause. Record the event that ended the call, not only the final status. The definition should match the platform's report and the client's contract."},{"heading":"Separate the queue stages","body":"Break the customer journey into the IVR, the queue, the transfer, and the agent greeting. A call abandoned in the IVR may never have reached the queue, while one abandoned after a long wait is a different problem. Report the stage for each abandoned call. A combined rate can hide a menu problem behind a staffing debate. A stage-by-stage report lets the client see whether the fix belongs in the menu or in the schedule."},{"heading":"Count the offered load correctly","body":"Use the calls that actually entered the queue as the denominator, not every call that reached the phone system. Remove test calls, duplicates, and calls that were blocked before the queue. Record the removal counts and the reason. A denominator that changes between reports makes the rate look like a trend when it is a definition change. Publish the definition with the report so the client can compare periods without guessing."},{"heading":"Measure the wait before the abandon","body":"Report the time the customer waited before leaving, not only the fact of the abandon. A cluster of very short waits suggests a menu or expectation problem, while a cluster near the service target suggests a capacity gap. Show the distribution by interval and by call type. A median can hide the customers who waited longest. Show the share of callers who waited longer than the stated target, not only the average."},{"heading":"Compare with agent availability","body":"Pair the abandon data with the number of agents logged in, available, and on other channels. A queue can abandon calls while agents are busy on chat or after-call work that the voice report does not show. Count the total workload, not only the voice occupancy. A capacity gap may be a channel-mix problem rather than a headcount problem. A voice-only view will overstate capacity when agents are already handling chat and email."},{"heading":"Check the callback option","body":"An abandoned call may be a customer who accepted a callback and left the queue. Treat that event as a deferred contact, not a lost one, if the callback was actually offered and recorded. Compare the callback kept rate with the abandon rate. A queue that hides a failed callback inside an abandon count is measuring the wrong thing. If the callback was not recorded, treat the event as an abandon and fix the offer."},{"heading":"Look for a sudden event","body":"A sharp change in abandon rate can come from an outage, a carrier issue, a menu change, or a marketing spike. Compare the interval with the system change log and the volume forecast. A staffing shortfall usually builds over several intervals, while an outage can appear in one. Do not add staff for a one-hour platform failure. Check the change log before the staffing plan so the team does not solve the wrong problem."},{"heading":"Test the platform's abandoned-call report","body":"Pull a small sample of call identifiers and compare the platform's status with the actual call detail. Check whether a short abandon is recorded, whether a transfer resets the timer, and whether a hang-up during a message is counted. Reconcile the total with the offered calls. A report that cannot be reproduced from the detail is not evidence. If the detail does not reproduce the report, correct the report before it reaches the client."},{"heading":"Separate customer behavior from capacity","body":"Some customers hang up because they changed their mind, found the answer elsewhere, or called back on another channel. Use the call reason and the repeat-contact data to identify those cases. Do not assume every abandon is a lost customer. Still, a rising repeat-contact rate after an abandon can show that the customer did not get help. Use the repeat-contact data to see whether the customer found help on another channel."},{"heading":"Compare intervals, not just the month","body":"A monthly abandon rate can hide a severe peak in a few intervals. Break the period into short intervals and compare the rate with the staffing plan for each one. Look for a repeated pattern at the same hour or day. A staffing fix should target the intervals where the gap is consistent. A heat map by hour and day makes a repeated peak easier to see than a monthly average."},{"heading":"Check the service-level target","body":"The abandon rate only makes sense beside the service-level target and the answer time. A queue that answers eighty percent of calls in twenty seconds may have a different abandon pattern from one that answers fifty percent. Report the target, the achieved level, and the abandon rate together. A target that is too tight for the volume can create unnecessary cost."},{"heading":"Review the shrinkage assumption","body":"A staffing plan may assume a certain amount of breaks, meetings, and absence. If the real shrinkage is higher, the plan will understaff the queue even when the headcount looks correct. Compare the planned and actual shrinkage for the same period. A gap there can explain the abandon pattern without a new hire. If the gap is large, fix the shrinkage assumption before adding a permanent shift."},{"heading":"Test a small staffing change","body":"Before adding a full shift, test a small change in one interval, such as moving a break or adding one agent. Measure the abandon rate, the wait time, and the answer rate for the same interval. Compare with a similar interval that did not change. A small test is cheaper than a permanent schedule change based on a noisy month."},{"heading":"Report the cost of the gap","body":"Estimate the calls abandoned and the repeat contacts that followed. Do not price a lost customer without evidence. Show the added workload and the service result beside the cost of the proposed staffing change. The client should see the tradeoff, not only a rate. State the assumptions in the report. Show the range around the estimate so the client can see how uncertain it is."},{"heading":"Document what the log cannot show","body":"An abandoned-call log cannot show what the customer would have said or whether the issue was resolved elsewhere. It cannot prove that a specific agent or shift caused the abandon. State the limits in the report and the sample size. Use the log to frame a question for operations, not to settle a performance dispute. State the sample size and the period so a reader does not treat a small pattern as a rule."},{"heading":"Review after a queue change","body":"A new IVR, a changed greeting, or a new channel can shift the abandon pattern without any staffing change. Review the log before and after the change, using the same definition and interval. Check the menu drop-off and the callback offer. A queue change that looks small can move the point of abandonment. Compare the menu drop-off and the queue wait separately so the cause is visible."},{"heading":"Write the staffing recommendation","body":"A recommendation should name the interval, the evidence, the proposed change, and the expected effect. Include the cost, the lead time, and the measure that will show whether it worked. Do not recommend a headcount change from a single rate. The client should be able to approve or reject a specific action. Write the measure and the review date before the change so the result is not judged by memory."},{"heading":"Limits of the evidence","body":"This brief cannot decide the right headcount for a specific queue, because the answer depends on the client's service target, budget, and channel mix. A log can show where customers leave and how long they waited, but it cannot prove the cause by itself. The sample may miss a rare event. Use the result to test a hypothesis, not to close the question."},{"heading":"Manager review questions","body":"Managers should ask which stage recorded the abandon, what the customer waited, and how many agents were actually available. They should also ask whether a callback was offered and whether the pattern repeats in the same intervals. The remaining question is what small change will be tested first. Record the answers with the period and the platform report. They should also ask which interval will be tested and what result would stop the change."},{"heading":"Conclusion","body":"An abandoned-call log proves a staffing shortfall only when the stage, the wait, the offered load, the agent availability, and the repeat contacts point the same way. A rate alone can reflect a menu, an outage, or a callback that failed. Compare intervals, test a small change, and state what the log cannot show. The evidence is useful when it leads to a specific schedule decision."}],"sources":[{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"NIST Cybersecurity Framework 2.0","organization":"National Institute of Standards and Technology","date":"2024","url":"https://www.nist.gov/cyberframework","note":"Govern, identify, protect, detect, respond, and recover functions used for control ownership."},{"name":"Privacy and Data Security Guidance","organization":"Federal Trade Commission","date":"2026","url":"https://www.ftc.gov/business-guidance/privacy-security","note":"Business guidance on protecting customer information and honoring privacy commitments."}],"keyStats":["2.67 million U.S. customer service representative jobs in 2025 (BLS)","$21.53 median hourly wage in May 2025 (BLS)","289,500 projected annual openings, 2025 to 2035 (BLS)"],"takeaways":["Report the abandonment stage and the wait time, not only the final abandon rate.","Use queue entries as the denominator and reconcile the platform total with call detail.","Pair the log with agent availability across voice, chat, and after-call work.","Test one interval-level staffing change before approving a permanent schedule."],"faqs":[{"question":"Does a high abandon rate always mean understaffing?","answer":"No. A menu delay, an outage, or a failed callback can raise the rate without a capacity gap. Check the stage and the wait distribution first."},{"question":"Should callback requests count as abandoned?","answer":"Track them separately as deferred contacts and measure whether the callback was kept. Folding them into the abandon rate hides the customer outcome."}],"related":["callcenteroutsourced-when-does-a-customer-survey-response-rate-support-a-site-comparison","callcenteroutsourced-how-should-a-split-shift-timekeeping-record-reconcile-with-the-schedule"],"internalLinks":["/research","/services","/contact-us"],"serviceHandoff":{"href":"/contact-us","label":"Review the queue design","body":"Bring the current queue rules, the shift handoff, and one week of cases so the review can test a real promise."}},{"slug":"callcenteroutsourced-when-should-a-queue-split-by-language-instead-of-by-skill","title":"When should a queue split by language instead of by skill?","excerpt":"A decision test for language versus skill routing, with demand evidence, service-level tradeoffs, and a review plan for the split.","published":"2026-11-17","sourceDate":"2026-11-17","updated":"2026-11-17","image":"/daily17/callcenteroutsourced/callcenteroutsourced-when-should-a-queue-split-by-language-instead-of-by-skill.webp","sections":[{"heading":"Question and scope","body":"This brief asks when a contact center should split a queue by language rather than by skill. The population is one client's inbound queue during a defined period, and the unit is a routing decision for a customer contact. The question is whether a language split improves access without creating idle capacity or losing context. The analysis covers demand, routing, and measurement, not the legal obligations of a specific service. Record the languages, the skills, and the period before comparing options."},{"heading":"What the evidence supports","body":"Census data shows that a substantial share of U.S. households speaks a language other than English at home, and federal language-access guidance calls for meaningful access for people with limited English proficiency. Contact-center standards call for routing to the right resource, but they do not prescribe a language queue design. The operating inference is to split only when the demand is large enough to staff a dedicated line and when the service gain is measurable. The design question is whether a dedicated queue produces a better outcome than a well-run interpreter line."},{"heading":"Measure the language demand","body":"Count the contacts where the customer asks for a language or where the agent needs language support. Use the customer's stated preference, not an inferred one. Record the language, the channel, the time, and the outcome. A small number of requests concentrated in a few hours may need a scheduled line rather than a full queue. A request that appears only in a monthly total may hide a peak that needs a scheduled line."},{"heading":"Separate language from skill","body":"A language is not the same as a product skill. A customer may need a Spanish-speaking agent who can also handle billing disputes. Map the language demand against the skill demand before choosing a split. A language-only queue can answer quickly and still transfer for the substantive work, which adds a second wait. A queue that cannot resolve the common request will transfer the customer and add a second wait."},{"heading":"Estimate the staffing floor","body":"A dedicated language queue needs enough agents to cover the hours when the demand arrives. Calculate the minimum coverage for breaks, absence, and peak intervals. If the volume supports only one agent, the queue may be fragile during a break or a sick day. Compare that risk with the current bilingual-agent model. A single-agent queue can fail during a break, so the plan needs a named backup."},{"heading":"Check the current routing","body":"Before the split, measure how the existing queue handles a language request. Does the call wait for a bilingual agent, transfer to a language line, or proceed with a family member interpreting? Each path has a different customer experience and a different record. A split may fix a problem that is actually a routing rule. The current path may already be a language line under a different name, so read the routing rules first."},{"heading":"Model the service-level tradeoff","body":"A language split can improve the wait for those customers while reducing the pool available for everyone else. Model the change with the real arrival pattern, not an average. Check the effect on the main queue during peak and overnight intervals. A design that helps one group and breaks another is not an improvement. Model the peak interval, because an average can hide the hour when the main queue breaks."},{"heading":"Protect the customer from a handoff","body":"A language queue should be able to finish the common requests without a second transfer. Give the agents the skills and the authority for the top call reasons. For work outside that scope, use a warm transfer with the context attached. Count the handoffs and the repeat explanations as part of the result. Count the warm transfers and the repeat explanations as part of the service result."},{"heading":"Set the language identification rule","body":"Ask the customer for the preferred language in the IVR and at the agent greeting. Do not route by the caller's name, area code, or accent. Offer a short list of the languages the queue actually supports and a path for any other language. Record the choice and the fallback. The IVR should offer a short list and a clear option for any other language."},{"heading":"Check the interpreter option","body":"A dedicated queue is not the only way to serve a language need. An interpreter line can cover a low-volume language or a complex call. Compare the cost, the wait, and the record quality of the two options. A queue with one agent may be less reliable than a well-run interpreter line. Compare the interpreter line's wait and record quality with the proposed queue before deciding."},{"heading":"Test with a small routing change","body":"Route a defined share of the language demand to the proposed queue for a short period. Measure the answer time, the transfer rate, the resolution, and the repeat contact for those customers. Compare with a similar period on the current path. Do not change the whole queue at once. Keep the rest of the traffic on the current path so the comparison has a control group."},{"heading":"Watch for a new bottleneck","body":"A language split can create a bottleneck at the language queue while the main queue has idle agents. Monitor the occupancy of both queues and the wait for each customer group. A dedicated queue that is always busy may need more staff, while one that is often idle may be too broad. Adjust the hours before adding headcount. Adjust the hours or the skill mix before adding headcount to a queue that is only sometimes busy."},{"heading":"Review the skill mix inside the language queue","body":"The agents in a language queue need more than fluency. They need the product knowledge, the systems access, and the authority to resolve the common requests. Audit the training and the quality sample for the new queue. A language match without the skill match can produce a polite transfer instead of a resolution. The quality sample should include a call in each supported language, not only the majority one."},{"heading":"Check the client's language obligations","body":"The client may have legal, contractual, or policy obligations to provide language access. Ask the client's compliance team which languages and channels are in scope. Do not promise a service level the queue cannot meet. Record the obligation and the design decision together. Record the obligation beside the design so a later change does not quietly reduce access for one language group."},{"heading":"Report the result by language","body":"Report the wait, the resolution, the transfer, and the repeat contact for each language group. Do not combine them into one average that hides a gap. Show the volume and the sample size beside each measure. The client should see whether the split improved access or only moved the wait. A combined average can hide a language group that waits twice as long as the others."},{"heading":"Set a review date","body":"Review the split after a full demand cycle, such as a quarter, and sooner if the client adds a market. Check the language mix, the hours, the staffing, and the service result. A queue that was justified at launch may no longer fit the demand. Write the review date into the client plan. The review should check the language mix, the hours, and the staffing together."},{"heading":"Plan for a language with low volume","body":"A language with a handful of calls a week may not support a queue. Use an interpreter line, a scheduled callback, or a partner resource. Record the option in the routing guide so an agent does not improvise. The customer should get a clear next step even when the volume is small. The routing guide should name the approved option so an agent does not improvise a transfer."},{"heading":"Protect the record","body":"Record the language used, the interpreter identifier when one is involved, and the customer's key words. Keep the record with the same retention as the call. A language split should not create a second, thinner record. The next agent should be able to continue without asking the customer to start over. The next agent should be able to continue the conversation without asking the customer to start over."},{"heading":"Limits of the evidence","body":"This brief cannot decide the right language mix for a specific market, because the answer depends on the customer population, the client's obligations, and the available staff. A demand count can support a routing decision, but it cannot prove that a split will improve resolution. The sample may miss a seasonal change. Use the result to define a test, not to settle the design."},{"heading":"Manager review questions","body":"Managers should ask which languages customers actually request, how many also need a product skill, and what the current path costs in wait and transfers. They should also ask whether an interpreter line would serve the low-volume languages better. The remaining question is which routing change will be tested first. Record the answers with the period and the demand data."},{"heading":"Conclusion","body":"A queue should split by language when the demand supports dedicated coverage, the skill mix can resolve the common requests, and the service gain is visible without breaking the main queue. A language match alone is not enough. Test a small routing change, measure by language, and review the design after a full cycle. The split is justified when the customer tells the story once and reaches a resolution."}],"sources":[{"name":"Language Use","organization":"U.S. Census Bureau","date":"2026","url":"https://www.census.gov/topics/population/language-use.html","note":"Data and reports on languages spoken in U.S. households and English proficiency."},{"name":"Language Access Resources","organization":"U.S. Department of Justice, Civil Rights Division","date":"2026","url":"https://www.justice.gov/crt/language-access-resources","note":"Federal guidance on providing meaningful access to people with limited English proficiency."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."}],"keyStats":["2.67 million U.S. customer service representative jobs in 2025 (BLS)","$21.53 median hourly wage in May 2025 (BLS)","289,500 projected annual openings, 2025 to 2035 (BLS)"],"takeaways":["Split only when measured language demand supports coverage across breaks, peaks, and absences.","Map language demand against product skills so the new queue can resolve, not just translate.","Test a share of traffic and compare wait, transfers, resolution, and repeat contact by language.","Use an interpreter line for low-volume languages and record that option in the routing guide."],"faqs":[{"question":"Should a queue route by the caller's accent or name?","answer":"No. Ask for the preferred language and record the answer. Inferring language from a name or accent creates errors and can offend the customer."},{"question":"Is a dedicated language queue always better than an interpreter line?","answer":"No. A dedicated queue fits steady volume and common requests, while an interpreter line can cover low-volume or complex calls with less idle capacity."}],"related":["callcenteroutsourced-how-should-a-split-shift-timekeeping-record-reconcile-with-the-schedule","callcenteroutsourced-what-does-a-callback-consent-record-need-to-survive-a-complaint-review"],"internalLinks":["/research","/services","/contact-us"],"serviceHandoff":{"href":"/contact-us","label":"Review the queue design","body":"Bring the current queue rules, the shift handoff, and one week of cases so the review can test a real promise."}},{"slug":"callcenteroutsourced-how-should-a-contact-center-measure-adherence-without-punishing-legitimate-exceptions","title":"How should a contact center measure adherence without punishing legitimate exceptions?","excerpt":"An adherence measure that separates schedule changes, approved exceptions, and unexcused time before it reaches a performance review.","published":"2026-11-17","sourceDate":"2026-11-17","updated":"2026-11-17","image":"/daily17/callcenteroutsourced/callcenteroutsourced-how-should-a-contact-center-measure-adherence-without-punishing-legitimate-exceptions.webp","sections":[{"heading":"Question and scope","body":"This brief asks how an outsourced contact center should measure schedule adherence without punishing agents for legitimate exceptions. The population is one queue and one review period, and the unit is an agent-day with a scheduled shift. The question is whether the measure separates approved changes from unexcused deviation. The analysis covers definition, evidence, and review, not the legal classification of a specific absence. Record the schedule version, the timekeeping source, and the period before sampling."},{"heading":"What the evidence supports","body":"Federal wage-and-hour guidance requires accurate records of hours worked and payment for compensable time. Contact-center standards call for schedule adherence as a performance measure, but they do not define which exceptions should be excused. The operating inference is to measure adherence against the schedule in force and to report approved exceptions separately. A single percentage that mixes a system outage with an unexcused absence cannot support a fair review."},{"heading":"Define adherence precisely","body":"Adherence usually compares the time an agent is scheduled to be available with the time the agent is actually available. Write the start and end of the comparison, including meetings, training, and after-call work. Decide whether a login that is ready but not taking calls counts as adherent. The definition should be the same for every team in the comparison."},{"heading":"Freeze the schedule version","body":"A schedule can change after the shift through a client request, a supervisor edit, or a system update. Record which version was in force for each agent-day and who approved the change. Compare the agent's time against that version, not against the schedule published later. A measure that uses the wrong version punishes an agent for following the instruction they received."},{"heading":"Classify every exception","body":"Build a short list of exception types: approved shift change, approved break, system outage, training, sick leave, and unexcused deviation. Give each type a code and an owner. The code should be applied at the time of the event, not reconstructed at review. A clear list turns a disputed percentage into a set of specific cases. Each code should have a written example so two supervisors apply it the same way."},{"heading":"Separate paid work from adherence","body":"An agent can be adherent and still not productive, or productive while off the schedule. Keep the adherence measure separate from occupancy, handle time, and quality. A training session may lower adherence while improving the queue later. Report the measures side by side so a manager does not trade one for another without a decision. Report the measures side by side so a manager does not trade quality for a schedule number."},{"heading":"Protect approved breaks and rest periods","body":"A rest break is part of the workday, and a missed break can be a compliance issue rather than an adherence failure. Record the break start and end and whether it was interrupted. If the queue cannot release the agent on time, the schedule or the staffing is the problem. Do not ask the agent to choose between a break and a score."},{"heading":"Handle a system outage","body":"When the phone system or the CRM is unavailable, the agent may be logged in but unable to work. Create an outage code that a supervisor can apply to the affected interval. Record the start, the end, and the systems involved. The code should remove the interval from the unexcused calculation without hiding the service impact. The outage code should not hide the service impact from the client report."},{"heading":"Check the timekeeping source","body":"Compare the phone login, the timekeeping punch, and the schedule for a sample of agent-days. A login can be late because the system was slow, while a punch can be missing because the agent used a different device. Record the source used for the measure and the reason for any correction. A correction without an audit trail is not evidence."},{"heading":"Set the review threshold by role","body":"A supervisor, a new agent, and a tenured agent may have different scheduled meetings and coaching time. Set the adherence expectation by role and by schedule type, not one number for the whole floor. A new agent in training should not be measured against a fully productive shift. Publish the rule before the period starts. Publish the expectation by role before the period so the score is not a surprise."},{"heading":"Train managers on the exception codes","body":"A code is only useful if supervisors apply it consistently. Train them with examples of an approved change, a system outage, and an unexcused late start. Calibrate a small set of cases across supervisors and compare the codes. A disagreement about the same case is a definition problem, not an agent problem. Calibrate a small set of cases across supervisors and compare the codes they choose."},{"heading":"Give the agent a view of the record","body":"An agent should be able to see the schedule, the punches, and the exception codes before the review. A surprise score at the end of the month invites a dispute. Let the agent flag a missing code or a wrong schedule version. Record the correction and the reason. A correction should show the original value, the new value, the reason, and the reviewer."},{"heading":"Review a sample before the score","body":"Before publishing the monthly adherence result, pull a sample of low scores and read the underlying records. Check the schedule version, the exception code, and the timekeeping source. Fix the data before the score reaches a performance conversation. A measure that is wrong for a few agents is wrong for the report. Fix the data before the score reaches a performance conversation."},{"heading":"Avoid a single ranking","body":"A ranking by adherence alone can reward an agent who takes fewer breaks or skips coaching. Pair the measure with quality, resolution, and attendance. Show the exception mix beside the score. A team with many approved changes may look less adherent while following the client's actual demand. Show the exception mix beside the score so a team with many approved changes is not penalized."},{"heading":"Test a schedule change","body":"When the client changes a shift or adds a meeting, test the adherence calculation before the first live period. Check the new start and end, the break, and the exception codes. Review one agent-day with the supervisor and one with payroll. A small schedule change can create a coding gap that affects the whole team. Review one agent-day with the supervisor and one with payroll before the first live period."},{"heading":"Report to the client","body":"Give the client the adherence result, the exception counts by type, the schedule versions, and the sample size. Separate the unexcused deviation from the approved exceptions. Do not send a single percentage without the mix. The client should see where the queue followed the plan and where the plan changed. A single percentage without the exception mix invites a conclusion the data cannot support."},{"heading":"Document the limits","body":"An adherence measure cannot show whether the agent was working productively during the scheduled time. It also cannot prove that every exception was coded correctly. State the source, the period, and the sample. Use the result to improve the schedule and the coding, not to claim a complete picture of performance. State the source, the period, and the sample in the report."},{"heading":"Review after a system change","body":"A new phone platform or timekeeping tool can change the login event, the rounding, and the exception code. Recheck the measure before and after the change with the same sample. Compare the agent-day result, not only the report total. Update the definition and the training if the source changed. Update the definition and the training if the login event or the rounding changed."},{"heading":"Keep the record for the review period","body":"Keep the schedule versions, the punches, the exception codes, and the correction log for as long as the client and the law require. Limit who can edit a punch and review the access log. A record that can be changed without a trace cannot support a fair adherence review. An edit without that trail cannot support a fair review of the agent's time."},{"heading":"Limits of the evidence","body":"This brief cannot decide whether a specific absence or schedule change should be excused, because that depends on the client's policy and the facts. A measure can show what the record contains and where the coding is inconsistent. The sample may miss a rare exception. Use the result to fix the definition and the evidence, not to settle an individual dispute."},{"heading":"Manager review questions","body":"Managers should ask which schedule version was used, how each exception was coded, and who approved a correction. They should also ask whether the agent could see the record before the review and whether the same case would be coded the same way by another supervisor. The remaining question is which code or source needs fixing. Record the answers with the period and the sample."},{"heading":"Conclusion","body":"An adherence measure is fair when it uses the schedule in force, separates approved exceptions from unexcused deviation, and shows the agent the record before the review. A single percentage hides the difference between a system outage and a missed shift. Calibrate the codes, sample the low scores, and report the mix with the result. The measure is useful when it improves the schedule and the evidence, not when it only ranks people."}],"sources":[{"name":"Fact Sheet #64: Call Centers under the Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2008","url":"https://www.dol.gov/agencies/whd/fact-sheets/64-flsa-call-centers","note":"Hours-worked, rest-period, and recordkeeping rules for call center employees."},{"name":"Fair Labor Standards Act","organization":"U.S. Department of Labor, Wage and Hour Division","date":"2026","url":"https://www.dol.gov/agencies/whd/flsa","note":"Federal minimum wage, overtime, hours-worked, and recordkeeping obligations."},{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."}],"keyStats":["2.67 million U.S. customer service representative jobs in 2025 (BLS)","$21.53 median hourly wage in May 2025 (BLS)","289,500 projected annual openings, 2025 to 2035 (BLS)"],"takeaways":["Freeze the schedule version in force and compare the agent-day to that version, not a later edit.","Code approved changes, outages, breaks, and unexcused deviation separately before review.","Check the phone login, timekeeping punch, and schedule for the same sample and log corrections.","Let agents see the record before the review and calibrate exception codes across supervisors."],"faqs":[{"question":"Is schedule adherence the same as attendance?","answer":"No. Adherence compares available time with the schedule; attendance records whether the agent showed up. A single measure cannot answer both questions."},{"question":"Should a system outage be excused?","answer":"Code it separately when the agent was logged in but unable to work. The interval still matters for service, but it should not count as an unexcused deviation."}],"related":["callcenteroutsourced-how-should-a-split-shift-timekeeping-record-reconcile-with-the-schedule","callcenteroutsourced-when-does-a-customer-survey-response-rate-support-a-site-comparison"],"internalLinks":["/research","/services","/contact-us"],"serviceHandoff":{"href":"/contact-us","label":"Review the queue design","body":"Bring the current queue rules, the shift handoff, and one week of cases so the review can test a real promise."}},{"slug":"callcenteroutsourced-what-does-a-quality-calibration-record-need-to-survive-a-client-audit","title":"What does a quality calibration record need to survive a client audit?","excerpt":"The evidence a quality calibration record needs: the sample, the rubric, the disagreements, the decision, and the follow-up after the session.","published":"2026-11-17","sourceDate":"2026-11-17","updated":"2026-11-17","image":"/daily17/callcenteroutsourced/callcenteroutsourced-what-does-a-quality-calibration-record-need-to-survive-a-client-audit.webp","sections":[{"heading":"Question and scope","body":"This brief asks what a quality calibration record should contain to survive a client audit. The population is one queue and one review period, and the unit is a calibration session that compares evaluator scores on the same calls. The question is whether the record shows a controlled method rather than a meeting with a summary. The analysis covers sampling, scoring, disagreement, and follow-up, not the design of the quality rubric itself. Record the queue, the period, and the evaluators before sampling."},{"heading":"What the evidence supports","body":"Quality-management and contact-center standards call for defined criteria, trained evaluators, and a documented review process. Federal data-quality guidance calls for documenting sources, testing reliability, and stating limitations. None of these sources supplies a universal calibration form. The operating inference is to keep the sample, the rubric version, the individual scores, the disagreement, and the resulting decision in one record. The record should let a reviewer follow one call from selection to the final decision."},{"heading":"Define the calibration unit","body":"A calibration session should compare evaluators on the same call and the same rubric version. The unit is an evaluator-score for one call, not the session average. Record the call identifier, the evaluator, the score, and the date. A session average can hide a pattern where one evaluator is consistently stricter on the same criteria. A session average can hide a pattern where one evaluator is stricter on the same criterion."},{"heading":"Select the sample before the session","body":"Choose calls that represent the common reasons, the difficult cases, and at least one call with a disputed outcome. Do not let an evaluator pick only the calls that make a point. Record the selection rule and the population it came from. A sample chosen after the discussion cannot test agreement. A sample chosen after the discussion cannot test whether evaluators agree before they talk."},{"heading":"Freeze the rubric version","body":"A rubric that changes during the session makes the scores incomparable. Record the version, the criteria, and the scoring scale used for each call. If the rubric changes as a result of the session, mark the change and the date. Do not edit the old scores to fit the new wording. If the wording changes, mark the change and the date instead of editing the old scores."},{"heading":"Score independently first","body":"Each evaluator should score the call before the group discussion. Record the individual scores and the comments separately. A score collected after the discussion measures conformity, not agreement. Keep the independent sheet with the final record so a reviewer can see the starting point. The independent sheet is the evidence that the discussion changed a score, not the record of the session."},{"heading":"Record the disagreement, not only the consensus","body":"A calibration record is most useful when it shows where the evaluators disagreed. Record the criterion, the scores, and the reason each evaluator gave. A record that shows only the final agreed score loses the information that would improve the rubric. Do not erase the original scores. Erasing the original scores loses the information that would improve the rubric and the training."},{"heading":"Name the decision and the owner","body":"Every disagreement should end in a decision: the rubric is clear, the rubric needs a change, or the case needs a policy answer. Record the decision, the owner, and the date. A session that ends with a general agreement to be more consistent has not produced a control. The decision should be specific enough to apply to the next call."},{"heading":"Check the scoring scale","body":"A five-point scale can hide a pattern if evaluators use only the top and bottom. Compare the distribution of scores by criterion and by evaluator. A criterion with no middle scores may be poorly worded or rarely observed. Record the distribution beside the agreement result. A criterion with no middle scores may be poorly worded or rarely observed in the sample."},{"heading":"Measure agreement in a usable way","body":"Choose a method that fits the scale and the sample size, and state it in the record. Do not report a single agreement percentage without the method and the sample. For a small sample, describe the disagreement in counts and examples rather than a precise statistic. The client should be able to follow the calculation. For a small sample, report the disagreement in counts and examples rather than a precise statistic."},{"heading":"Test the record with a new evaluator","body":"Give the record to an evaluator who did not attend the session. Ask them to reconstruct the call, the scores, and the decision. If they cannot, the record is missing a link. This test is more useful than a sign-off page because it shows whether the evidence is usable. If the new evaluator cannot reconstruct the call, the record is missing a link."},{"heading":"Keep the call evidence","body":"The calibration record should link to the recording, the transcript, and the case note used in the session. If the call is deleted under the retention rule, record that fact and the date. Do not keep only a summary of the call. A later auditor should be able to check the score against the evidence. If the call was deleted under the retention rule, record that fact and the date."},{"heading":"Handle a disagreement with the client","body":"The client may score the same call differently or interpret the rubric in its own way. Record the client's position, the queue's position, and the decision. Do not change the score without a documented reason. A calibration record that hides a client disagreement cannot support the next review. A record that hides a client disagreement cannot support the next review."},{"heading":"Review the follow-up actions","body":"At the next session, check whether the previous decisions were applied. Look for a rubric change, a coaching note, or a policy answer. A decision with no follow-up is a meeting note, not a control. Record the status of each action and the owner. A decision with no follow-up is a meeting note, not a control the client can audit."},{"heading":"Sample across teams and sites","body":"A calibration record from one supervisor may not represent another site. Include evaluators from each team that scores the same queue, especially when the client compares sites. Record the site and the team with each score. A local agreement can coexist with a cross-site disagreement. A local agreement can coexist with a cross-site disagreement, so report both in the client summary."},{"heading":"Protect the evaluator's independence","body":"An evaluator should be able to record a score without pressure to match a supervisor. Keep the independent sheet and the discussion notes separate. Do not attribute a disagreement to an individual in the client report unless the client needs it for a specific review. The goal is a better rubric, not a blame record. The goal is a better rubric, not a blame record for the individual evaluator."},{"heading":"Report the result to the client","body":"Give the client the sample, the rubric version, the agreement result, the disagreements, and the actions. Use examples rather than a single percentage. State what the session could not resolve. The report should let the client see whether the quality score is reliable enough for the decision it supports. The report should let the client see whether the score is reliable enough for the decision it supports."},{"heading":"Review after a rubric change","body":"A new rubric needs a new calibration before it is used for performance. Test the wording with the same calls where possible, and record the scores under both versions. A change that looks clearer on paper may create a new disagreement in practice. Update the training and the quality checklist together. Update the training and the quality checklist on the same day as the rubric change."},{"heading":"Check the retention of the record","body":"Keep the calibration records, the rubric versions, and the linked evidence for the period the client and the law require. Limit who can edit a score and review the access log. A record that can be changed without a trace is weak evidence in an audit. A score that can be changed without a trace is weak evidence in an audit."},{"heading":"Limits of the evidence","body":"This brief cannot prove that a quality score is valid for every purpose, because validity depends on the rubric, the sample, and the decision. A calibration record can show a controlled comparison, but it cannot remove evaluator judgment. The sample may miss a rare call type. Use the result to improve the method and to state the limits honestly. Use the result to improve the method and to state the limits honestly."},{"heading":"Manager review questions","body":"Managers should ask which calls were selected, which rubric version was used, and whether the scores were collected independently. They should also ask what decision came from the largest disagreement and whether it was applied. The remaining question is which criterion still produces a split. Record the answers with the period and the sample. They should also ask which criterion still produces a split and what change will be tested next."},{"heading":"Conclusion","body":"A quality calibration record survives a client audit when it preserves the sample, the rubric version, the independent scores, the disagreement, the decision, and the follow-up. A consensus summary alone cannot show whether the method is reliable. Test the record with a new evaluator and link it to the call evidence. The record is useful when a reviewer can reconstruct the session and see what changed."}],"sources":[{"name":"ISO 18295-1:2017 Customer contact centres","organization":"International Organization for Standardization","date":"2017","url":"https://www.iso.org/standard/64739.html","note":"Requirements for customer contact centre processes, people, and performance."},{"name":"GAO-20-283G: Assessing Data Reliability","organization":"U.S. Government Accountability Office","date":"2020","url":"https://www.gao.gov/products/gao-20-283g","note":"A practical framework for documenting data sources, testing reliability, and stating limitations."},{"name":"NIST Cybersecurity Framework 2.0","organization":"National Institute of Standards and Technology","date":"2024","url":"https://www.nist.gov/cyberframework","note":"Govern, identify, protect, detect, respond, and recover functions used for control ownership."},{"name":"Privacy and Data Security Guidance","organization":"Federal Trade Commission","date":"2026","url":"https://www.ftc.gov/business-guidance/privacy-security","note":"Business guidance on protecting customer information and honoring privacy commitments."},{"name":"Occupational Outlook Handbook: Customer Service Representatives","organization":"Bureau of Labor Statistics","date":"2026","url":"https://www.bls.gov/ooh/office-and-administrative-support/customer-service-representatives.htm","note":"Employment, wage, training, and outlook figures for customer service representatives."}],"keyStats":["2.67 million U.S. customer service representative jobs in 2025 (BLS)","$21.53 median hourly wage in May 2025 (BLS)","289,500 projected annual openings, 2025 to 2035 (BLS)"],"takeaways":["Keep independent scores, the rubric version, and the selected sample with the session record.","Record disagreements by criterion and evaluator; do not erase them when the group agrees.","Name a decision and an owner for each disagreement and check the follow-up at the next session.","Test the record with a new evaluator and link every score to the call evidence."],"faqs":[{"question":"Should the calibration record show only the agreed score?","answer":"No. The independent scores and the disagreement show whether the rubric is clear and where evaluators need training."},{"question":"How many calls should a calibration session review?","answer":"Enough to cover the common reasons and the difficult cases within the available time. Record the selection rule and the sample size so the result is not overstated."}],"related":["callcenteroutsourced-how-should-a-contact-center-validate-an-ai-generated-call-summary","callcenteroutsourced-what-does-a-call-recording-retention-schedule-prove-under-review"],"internalLinks":["/research","/services","/contact-us"],"serviceHandoff":{"href":"/contact-us","label":"Review the queue design","body":"Bring the current queue rules, the shift handoff, and one week of cases so the review can test a real promise."}}] as unknown as readonly ResearchPost[];
